require_once __DIR__.'/config.php'; require_login(); if(!fams_current_type_allows('AICS','view_records')){http_response_code(403);exit('Your user type does not have permission to view assistance records. Contact the LPGMA Site Administrator if this access is required.');} $pageTitle='Centralized Masterlist'; $user=current_user()??[];
$isLpgmaWorkspaceUser = (function_exists('fams_current_lpgma_user_id') && fams_current_lpgma_user_id()>0) || in_array((string)($_SESSION['fams_identity']??''),['LPGMA','LPGMA_BRIDGED'],true) || (($user['identity_source']??'')==='LPGMA_BRIDGED') || ((int)($user['office_id']??0)===1 && ($user['role']??'')!=='social_worker');
if ($_SERVER['REQUEST_METHOD']==='POST' && (string)($_POST['action']??'')==='restore_record') { http_response_code(405); header('Allow: GET'); exit('Restoration is available only through the administrator Deleted Entries workflow.'); }
if ($_SERVER['REQUEST_METHOD']==='POST' && (string)($_POST['action']??'')==='delete_record') {
    if (!fams_current_type_allows('AICS','edit_records')) { http_response_code(403); exit('Your user type cannot delete assistance records.'); }
    verify_csrf(); $id=(int)($_POST['id']??0);
    try {
        if($id<1) throw new RuntimeException('Invalid record selected.');
        fams_shared_transaction($pdo,function(PDO $db) use($id,$isLpgmaWorkspaceUser){
            $st=$db->prepare('SELECT * FROM aics_assistance_records WHERE id=? LIMIT 1 FOR UPDATE');
            $st->execute([$id]); $row=$st->fetch(PDO::FETCH_ASSOC);
            if(!$row) throw new RuntimeException('Entry not found.');
            if(!can_access_record_scope($row)) throw new RuntimeException('This record is outside your assigned editing scope.');
            if(!user_is_admin() && (!$isLpgmaWorkspaceUser || strtoupper((string)($row['status']??''))!=='WAITING')) throw new RuntimeException('Only LPGMA users may directly delete WAITING entries. Locked entries require an administrator ticket.');
            fams_archive_record_with_history($db,'aics','',$row,(int)(current_user()['id']??0));
            $del=$db->prepare('DELETE FROM aics_assistance_records WHERE id=?'); $del->execute([$id]);
            if($del->rowCount()!==1) throw new RuntimeException('The entry changed before it could be archived. Reload the masterlist and try again.');
            log_action($db,'ARCHIVE_ASSISTANCE_RECORD','Moved assistance record '.$row['control_number'].' to Trash.',$id);
        });
        flash('success','Entry moved to Trash. You can restore it from Deleted Entries.');
    } catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack(); flash('error','Unable to process entry: '.$e->getMessage()); }
    redirect('records.php');
}
$q=fams_shared_normalize_search(query_value('q')); $status=query_value('status'); $type=query_value('type'); $office=(int)($_GET['office']??0); if($office===1){$office=0;} $page=max(1,(int)($_GET['page']??1)); $per=25;
// Centralized visibility: SWAD users can see all offices, while own-office records are sorted first. Editing/status/deletion authorization remains scope-checked per row.
$ownOfficeId=(int)($user['office_id']??0); $isSwadScopedUser=in_array(($user['role']??''),['social_worker','staff'],true) && $ownOfficeId>1;
// SWAD masterlists are district-wide: office and status filters must never hide records from SWAD accounts.
if($isSwadScopedUser){$status='';$office=0;}
$where=[];$params=[];
if($q!==''){ $where[]="(r.control_number LIKE ? OR r.client_first_name LIKE ? OR r.client_middle_name LIKE ? OR r.client_last_name LIKE ? OR r.beneficiary_first_name LIKE ? OR r.beneficiary_middle_name LIKE ? OR r.beneficiary_last_name LIKE ? OR r.municipality LIKE ? OR r.barangay LIKE ? OR r.contact_number LIKE ?)"; for($i=0;$i<10;$i++)$params[]='%'.$q.'%';}
if(in_array($status,['WAITING','RELEASED','CANCELLED'],true)){ $where[]='r.status=?';$params[]=$status; }
if(in_array($type,fa_types(),true)){ $where[]='r.assistance_type=?';$params[]=$type; }
if($office>0){$where[]='r.office_id=?';$params[]=$office;}
$base=' FROM aics_assistance_records r LEFT JOIN aics_offices o ON o.id=r.office_id '.($where?' WHERE '.implode(' AND ',$where):'');
$st=$pdo->prepare('SELECT COUNT(*)'.$base);$st->execute($params);$count=(int)$st->fetchColumn();$pageWindow=fams_shared_page_window($count,$page,$per);$pages=$pageWindow['pages'];$page=$pageWindow['page'];$offset=$pageWindow['offset'];
$order=$isSwadScopedUser ? ' ORDER BY CASE WHEN r.office_id='.((int)$ownOfficeId).' THEN 0 ELSE 1 END, r.date_submission DESC,r.id DESC' : ' ORDER BY r.date_submission DESC,r.id DESC';
$st=$pdo->prepare('SELECT r.*,o.name office_name'.$base.$order.' LIMIT '.$per.' OFFSET '.$offset);$st->execute($params);$rows=$st->fetchAll();
$offices=array_values(array_filter(office_rows($pdo),static function($o){return (int)($o['id']??0)!==1 && strtoupper(trim((string)($o['name']??'')))!=='LPGMA';}));
$showRecordActions = true;
$isNonAdminLpgma = $isLpgmaWorkspaceUser && !user_is_admin() && !in_array(($user['role']??''),['manager','staff'],true); require __DIR__.'/partials/header.php';
