pup('record_form.php?id=<?=$r['id']?>&popup=1')" aria-label="Edit record" title="Edit record"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M4 16.5V20h3.5L19 8.5 15.5 5 4 16.5Z"/><path d="m13.8 6.7 3.5 3.5"/></svg></button><?php elseif(fams_current_type_allows('AICS','submit_tickets')): ?><button class="fams-icon-action fams-icon-action-ticket record-ticket-icon" type="button" onclick="openGlobalPopup('<?=can_access_record_scope($r)?'revision_ticket.php':'office_reassignment_ticket.php'?>?popup=1&record=<?=$r['id']?>')" aria-label="<?=can_access_record_scope($r)?'Submit record revision ticket':'Request office reassignment'?>" title="<?=can_access_record_scope($r)?'Submit Ticket':'Request Office Reassignment'?>"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M4 7.5A2.5 2.5 0 0 0 6.5 10v4A2.5 2.5 0 0 0 4 16.5V19h16v-2.5a2.5 2.5 0 0 1 0-5v-4A2.5 2.5 0 0 0 17.5 5H4Z"/><path d="M12 7.5v2m0 3v2m0 3v.5"/></svg></button><?php else: ?><span aria-label="No permitted action">—</span><?php endif; ?><?php if(can_edit_record($r) && (user_is_admin() || ($isLpgmaWorkspaceUser && strtoupper((string)$r['status'])==='WAITING'))): ?><form method="post" class="masterlist-delete-form" onsubmit="return confirm('Move this WAITING entry to Trash? An administrator can restore it later as a new entry.')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_record"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="fams-icon-action fams-icon-action-delete" type="submit" aria-label="Move to Trash" title="Move to Trash"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M4 7h16M9 7V4h6v3m-9 0 1 13h10l1-13M10 11v5m4-5v5"/></svg></button></form><?php elseif(can_access_record_scope($r) && fams_current_type_allows('AICS','submit_tickets')): ?><button class="fams-icon-action fams-icon-action-delete record-delete-ticket-icon" type="button" onclick="