<script>
(()=>{
 const form=document.getElementById('aicsMasterlistSearchForm'), body=document.getElementById('aicsMasterlistBody');
 if(!form||!body)return;
 const q=form.querySelector('[name="q"]'), status=form.querySelector('[name="status"]'), type=form.querySelector('[name="type"]'), office=form.querySelector('[name="office"]');
 let timer=0, seq=0, controller=null;
 const run=async(updateUrl=true)=>{
   const id=++seq; controller?.abort(); controller=new AbortController(); const tableRegion=body.closest('.table-wrap'); tableRegion?.setAttribute('aria-busy','true');
   const params=new URLSearchParams(); if(q?.value.trim())params.set('q',q.value.trim()); if(status?.value)params.set('status',status.value); if(type?.value)params.set('type',type.value); if(office?.value&&office.value!=='0')params.set('office',office.value);
   params.set('page','1');
   try{
     const response=await fetch('records.php?'+params.toString(),{credentials:'same-origin',signal:controller.signal,headers:{'X-Requested-With':'XMLHttpRequest'}});
     if(!response.ok)throw new Error('Search failed: '+response.status);
     const html=await response.text(); if(id!==seq)return;
     const doc=new DOMParser().parseFromString(html,'text/html'); const nextBody=doc.getElementById('aicsMasterlistBody');
     if(!nextBody)throw new Error('Search response did not contain the masterlist.');
     body.innerHTML=nextBody.innerHTML;
     const oldPager=document.querySelector('.pagination'), newPager=doc.querySelector('.pagination'); if(oldPager&&newPager)oldPager.innerHTML=newPager.innerHTML; const oldTotal=document.querySelector('.masterlist-hero-meta strong'),newTotal=doc.querySelector('.masterlist-hero-meta strong');if(oldTotal&&newTotal)oldTotal.textContent=newTotal.textContent;
     const oldNote=document.querySelector('.masterlist-table-head .table-note'),newNote=doc.querySelector('.masterlist-table-head .table-note'); if(oldNote&&newNote)oldNote.textContent=newNote.textContent;
     const heading=document.querySelector('#masterlistSearchHeading'); const newHeading=doc.querySelector('#masterlistSearchHeading'); if(heading&&newHeading)heading.querySelector('.masterlist-panel-hint').textContent=newHeading.querySelector('.masterlist-panel-hint')?.textContent||'';
     if(updateUrl){const url=new URL(location.href);['q','status','type','office','page'].forEach(k=>url.searchParams.delete(k));params.forEach((v,k)=>{if(v!=='1'||k!=='page')url.searchParams.set(k,v)});history.replaceState({},'',url);}
   }catch(error){if(error.name!=='AbortError'){console.warn('AICS live masterlist search:',error);window.FAMSShowToast?.('Unable to refresh the masterlist. Check your connection and try again.','error');}}finally{if(id===seq)tableRegion?.removeAttribute('aria-busy');}
 };
 q?.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>run(true),Number(window.FAMS_DEBOUNCE_MS)||260)});
 [status,type,office].forEach(el=>el?.addEventListener('change',()=>run(true)));
 form.addEventListener('submit',e=>{e.preventDefault();clearTimeout(timer);run(true)});
 form.querySelector('a[href="records.php"]')?.addEventListener('click',e=>{e.preventDefault();form.reset();run(true)});
})();
</script>
